css:
.p16c-page { display: grid; grid-template-rows: auto 1fr; min-height: 100cqh; overflow-x: clip; }
.p16c-page > .deck { grid-row: 2; align-self: center; }
.p16c-top { display: grid; gap: var(--s-2); width: 100%; max-width: 56rem; margin-inline: auto; padding: var(--s-3) var(--s-3) 0; grid-row: 1; }
.p16c-top:empty { display: none; }
.p16c-strip { --p16c-sh: 9rem; }
.p16c-strip--b { --p16c-sh: 4.5rem; }
.p16c-strip .deck { --card: max(var(--card-min), min(var(--card-max), calc(100cqw - 2rem), calc(100cqh - 2rem - var(--peek) - var(--s-3) - var(--controls-h) - var(--p16c-sh)))); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p16c-strip { --p16c-sh: 17rem; } .p16c-strip--b { --p16c-sh: 6rem; } }
@media (max-width: 21.25rem) { .p16c-strip { --p16c-sh: 22rem; } .p16c-strip--b { --p16c-sh: 7rem; } }
.p16c-win .deck-card__head { margin-top: 0; }
.p16c-face { gap: var(--s-2); }
.p16c-body { flex: 1 1 auto; min-height: 0; overflow: auto; display: grid; grid-auto-rows: min-content; gap: var(--s-3); align-content: start; padding-block: var(--s-1) var(--s-2); border-bottom: var(--w1) solid var(--rule); }
.p16c-msg { flex: none; display: grid; gap: var(--s-2); }
.p16c-msg:empty { display: none; }
.p16c-foot { flex: none; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: var(--s-2); }
.dialog__foot.p16c-foot2 { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); }
.p16c-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -1); }
.p16c-area { position: relative; }
.p16c-count { position: absolute; right: var(--s-2); bottom: var(--s-1); font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); pointer-events: none; background: var(--white); padding-inline: var(--s-1); }
.p16c-count.is-over { color: var(--ink); font-weight: var(--fw-bold); }
.textarea.p16c-ta { min-height: 4rem; padding-bottom: 1.375rem; resize: none; }
.p16c-pair { display: grid; grid-template-columns: repeat(auto-fit, minmax(9.5rem, 1fr)); gap: var(--s-3); align-items: start; }
.p16c-pair .field { grid-template-columns: minmax(0, 1fr); }
.p16c-pair .select { height: auto; min-width: 0; padding-block: var(--s-2); }
.p16c-pair .select > span { min-width: 0; flex: 1 1 auto; overflow: hidden; overflow-wrap: anywhere; }
.p16c-pair .select .motive { display: flex; max-width: 100%; }
.p16c-pair + .menu { margin-top: calc(var(--s-2) * -1); }
.p16c-full { grid-column: 1 / -1; }
.textarea.p16c-name { min-height: var(--ctl-h); padding: var(--s-2) var(--s-3); resize: none; overflow-wrap: anywhere; }
.btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p16c-tipw { position: relative; display: flex; min-width: 0; }
.p16c-tipw > .btn { flex: 1 1 auto; width: 100%; }
.p16c-tip { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }
.p16c-win .hint { font-size: var(--fs-small); }
.p16c-fade { opacity: 0.5; }
.p16c-pressed { border-width: var(--w2); border-color: var(--ink); text-decoration: underline; text-underline-offset: 0.25em; }

.dialog.p16c-dlg { max-height: 100%; }
.dialog__foot.p16c-foot3 { flex-direction: column; }
.dialog__foot.p16c-foot3 > * { flex: none; }
.p16c-dlg .dialog__body p + p { color: var(--muted); }
.p16c-dlg .banner { padding-inline: var(--s-3); }
.p16c-dlg .dialog__foot .p16c-tipw { position: relative; }
.p16c-dtip { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }

.p16c-above { display: contents; }
.p16c-list { max-height: 11.5rem; overflow: auto; grid-auto-rows: min-content; }
.p16c-list .menu__item { gap: var(--s-2); }
.p16c-expl { padding: 0 var(--s-3) var(--s-1); }
.p16c-pair { position: relative; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p16c-pair--open > .field:first-child { display: none; } }
.p16c-none { padding: var(--s-2) 0; max-width: var(--measure); }
.p16c-pair--tip { padding-bottom: 2.25rem; }
.p16c-tipv { position: absolute; z-index: 30; bottom: 0; right: 0; width: max-content; max-width: min(17.5rem, 80vw); }

@media (max-width: 21.25rem) {
  .composer { gap: var(--s-1); padding-inline: var(--s-1); }
  .composer .input { padding-inline: var(--s-1); }
  .composer .input::placeholder { font-size: var(--fs-small); }
}

.deck__stack:has(> .p16c-win) { width: min(var(--card-max), calc(100cqw - 2rem)); height: auto; }
.deck__stack:has(> .p16c-win) ~ .deck__controls { display: none; }
.p16c-win { position: relative; left: auto; bottom: auto; width: 100%; height: auto; min-height: var(--card-min); max-height: calc(100cqh - 2rem - var(--p16c-win-off, 0rem)); display: flex; flex-direction: column; }
.p16c-win .deck-card__face { position: relative; inset: auto; flex: 1 1 auto; min-height: 0; }
.p16c-win [class*="-body"], .p16c-win .deck-card__scroll { scrollbar-width: thin; scrollbar-color: var(--line) var(--white); }
.p16c-strip { --p16c-win-off: 9.5rem; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p16c-strip { --p16c-win-off: 19.5rem; } }
@media (max-width: 21.25rem) { .p16c-strip { --p16c-win-off: 29.5rem; } }
.p16c-strip.p16c-strip--b { --p16c-win-off: 5.5rem; }
@media (max-width: 21.25rem) { .p16c-strip.p16c-strip--b { --p16c-win-off: 8rem; } }

.p16c-body { scroll-snap-type: y mandatory; }
.p16c-above + * { scroll-snap-align: start; }

.p16c-count { position: static; display: block; text-align: right; padding: 0; background: none; pointer-events: auto; }
.textarea.p16c-ta { padding-bottom: var(--s-2); }
.p16c-area { display: grid; gap: var(--s-1); }

.p16c-foot:has(.p16c-tipw) { grid-auto-flow: row; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
.p16c-foot .p16c-tipw { display: contents; }
.p16c-foot .p16c-tipw > .tip { position: static; width: auto; max-width: none; grid-column: 1 / -1; grid-row: 2; order: 3; }
.p16c-pair .p16c-tipv, .p16c-tipv { position: static; grid-column: 1 / -1; width: auto; max-width: none; translate: none; }
.p16c-snaplist { scroll-snap-type: y mandatory; }
.p16c-lat { scroll-snap-align: start; }
